import os
from typing import Dict, Any
from huggingface_hub import InferenceClient

def get_model_output_with_metadata(prompt: str) -> Dict[str, Any]:
    client = InferenceClient(
        provider="hf-inference",
        api_key=os.getenv("HF_TOKEN")
    )

    response = client.text_generation(
        prompt=prompt,
        model="mistralai/Mistral-7B-Instruct-v0.3",
        max_new_tokens=100,
        details=True,
        stream=False
    )

    metadata = {
        "provider": "Hugging Face Inference",
        "model": response.details.model,
        "usage": {
            "prompt_tokens": response.details.prompt_tokens,
            "generated_tokens": response.details.generated_tokens,
            "total_tokens": response.details.prompt_tokens + response.details.generated_tokens
        },
        "finish_reason": response.details.finish_reason,
        "seed": response.details.seed if hasattr(response.details, 'seed') else None
    }

    return {
        "output": response.generated_text,
        "metadata": metadata
    }
